const msg = $json;
let from='';
if(msg.from){ from = (typeof msg.from==='string') ? msg.from : (msg.from.text || (msg.from.value && msg.from.value[0] && msg.from.value[0].address) || ''); }
let body = msg.text || '';
if(!body && msg.html) body = String(msg.html).replace(/<[^>]+>/g,' ');
if(!body) body = msg.snippet || '';
body = body.replace(/\s+/g,' ').trim().slice(0,4000);
return { json:{ gmail_id: msg.id||'', gmail_thread_id: msg.threadId||msg.id||'', subject: msg.subject||'', from: from, body: body } };

const src=$json.body||'';
const thread=$json.gmail_thread_id||'';
const re=/Nombre\s+([\s\S]*?)\s+E-?mail\s+([\s\S]*?)\s+Tel[eé]fono\s+([\s\S]*?)\s+Barrio\s*\/?\s*Localidad\s+([\s\S]*?)\s+Escrib[ií][\s\S]*?mensaje\s+([\s\S]*?)\s+Enviado desde/i;
const m=src.match(re);
let r;
if(m){ let email=m[2].trim(); const em=email.match(/[^\s<>\[\]()]+@[^\s<>\[\]()]+\.[^\s<>\[\]()]+/); if(em) email=em[0]; const loc=m[4].trim(); const con=m[5].trim(); r={ es_presupuesto:true, nombre_cliente:m[1].trim(), email:email, telefono:m[3].trim(), asunto:'Formulario web', mensaje:(loc?('Localidad: '+loc+'. '):'')+con, gmail_thread_id:thread }; }
else { r={ es_presupuesto:true, nombre_cliente:'', email:'', telefono:'', asunto:'Formulario web', mensaje:src.slice(0,500), gmail_thread_id:thread }; }
return { json:r };

